package org.example.spotifymixer.runtime;
import android.content.*;import android.os.*;import android.graphics.*;import android.util.LruCache;import java.net.*;import java.io.*;import java.util.concurrent.*;import java.util.function.Consumer;import org.json.*;
/** Bounded metadata and artwork loading. No track load or playback command. */
public final class PlaylistMetadataStore {
 public static final class Entry {public final String title,cover;public final long time;Entry(String title,String cover,long time){this.title=title;this.cover=cover;this.time=time;}}
 private static final ExecutorService IO=Executors.newFixedThreadPool(2);private static final Handler MAIN=new Handler(Looper.getMainLooper());
 private static final LruCache<String,Bitmap> IMAGES=new LruCache<String,Bitmap>(8*1024*1024){protected int sizeOf(String k,Bitmap v){return v.getByteCount();}};
 private static final String KEY="playlist_metadata_v1";
 public static Entry cached(SharedPreferences prefs,String uri){try{JSONObject row=new JSONObject(prefs.getString(KEY,"{}")).optJSONObject(uri);return row==null?null:new Entry(row.optString("title"),row.optString("cover"),row.optLong("time"));}catch(JSONException e){return null;}}
 private static synchronized void save(SharedPreferences prefs,String uri,Entry entry)throws Exception{JSONObject all=new JSONObject(prefs.getString(KEY,"{}"));if(all.length()>=128&&!all.has(uri))all.remove(all.keys().next());all.put(uri,new JSONObject().put("title",entry.title).put("cover",entry.cover).put("time",entry.time));if(!prefs.edit().putString(KEY,all.toString()).commit())throw new IOException("Could not save playlist metadata");}
 public static void load(SharedPreferences prefs,String uri,Consumer<Entry> done,Consumer<String> failed){Entry old=cached(prefs,uri);if(old!=null&&System.currentTimeMillis()-old.time>=0&&System.currentTimeMillis()-old.time<300000){MAIN.post(()->done.accept(old));return;}IO.execute(()->{try{PlaylistWire.Page p=NativeBridge.metadata(uri);if(p.loading||p.title.trim().isEmpty())throw new IOException("Playlist metadata is not ready");Entry entry=new Entry(p.title,p.cover,System.currentTimeMillis());save(prefs,uri,entry);MAIN.post(()->done.accept(entry));}catch(Exception e){MAIN.post(()->failed.accept("Playlist metadata unavailable. Open the playlist and refresh."));}});}
 public static void image(String cover,Consumer<Bitmap> done){Bitmap old=IMAGES.get(cover);if(old!=null){done.accept(old);return;}IO.execute(()->{Bitmap image=null;try{if(cover.startsWith("spotify:mosaic:")){String[] ids=cover.substring(15).split(":");if(ids.length==4){Bitmap target=Bitmap.createBitmap(256,256,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(target);Paint paint=new Paint(Paint.FILTER_BITMAP_FLAG);for(int i=0;i<4;i++){if(!ids[i].matches("[a-fA-F0-9]{40}"))throw new IOException("Invalid mosaic");Bitmap tile=download("https://i.scdn.co/image/"+ids[i]);if(tile==null)throw new IOException("Missing artwork");canvas.drawBitmap(tile,null,new Rect((i%2)*128,(i/2)*128,(i%2+1)*128,(i/2+1)*128),paint);}image=target;}}else{String url=cover.matches("spotify:image:[a-fA-F0-9]{40}")?"https://i.scdn.co/image/"+cover.substring(14):cover;image=download(url);}if(image!=null)IMAGES.put(cover,image);}catch(Exception ignored){}Bitmap result=image;MAIN.post(()->done.accept(result));});}
 private static Bitmap download(String value)throws Exception{URL url=new URL(value);String host=url.getHost();if(!url.getProtocol().equals("https")||url.getUserInfo()!=null||url.getPort()!=-1||!(host.equals("i.scdn.co")||host.endsWith(".scdn.co")||host.endsWith(".spotifycdn.com")))throw new IOException("Unsupported cover source");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(8000);c.setReadTimeout(8000);try{if(c.getResponseCode()!=200)throw new IOException("Cover unavailable");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1){if(out.size()+n>2*1024*1024)throw new IOException("Cover too large");out.write(bytes,0,n);}}byte[] bytes=out.toByteArray();BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);if(bounds.outWidth<1||bounds.outHeight<1||bounds.outWidth>8192||bounds.outHeight>8192)throw new IOException("Invalid cover dimensions");BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=1;while(Math.max(bounds.outWidth,bounds.outHeight)/options.inSampleSize>512)options.inSampleSize*=2;return BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);}finally{c.disconnect();}}
 private PlaylistMetadataStore(){}
}
